import{_ as e,o as a,c as l,a2 as n}from"./chunks/framework.CZGNF-7T.js";const f=JSON.parse('{"title":"기안 양식 안내 (17종 전용 폼)","description":"","frontmatter":{},"headers":[],"relativePath":"approval/forms.md","filePath":"approval/forms.md","lastUpdated":1787896333000}'),s={name:"approval/forms.md"};function d(o,t,r,i,p,g){return a(),l("div",null,[...t[0]||(t[0]=[n(`<h1 id="기안-양식-안내-17종-전용-폼" tabindex="-1">기안 양식 안내 (17종 전용 폼) <a class="header-anchor" href="#기안-양식-안내-17종-전용-폼" aria-label="Permalink to &quot;기안 양식 안내 (17종 전용 폼)&quot;">​</a></h1><p>IBS 전자결재 시스템은 업무 효율성과 데이터 정합성을 위해 각 업무 도메인별로 최적화된 <strong>17종 전용 양식</strong>을 지원합니다.</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki material-theme-palenight vp-code" tabindex="0"><code><span class="line"><span>[17종 전용 양식]</span></span>
<span class="line"><span> ├─ 1. 일반 / 공통 (2종)</span></span>
<span class="line"><span> │    ├─ 일반 업무 품의서 (GENERAL)</span></span>
<span class="line"><span> │    └─ 공문 발신 품의서 (OFFICIAL_LETTER)</span></span>
<span class="line"><span> ├─ 2. 인사 / 근태 (5종)</span></span>
<span class="line"><span> │    ├─ 휴가 / 연차 신청서 (LEAVE)</span></span>
<span class="line"><span> │    ├─ 출장 신청서 (BUSINESS_TRIP)</span></span>
<span class="line"><span> │    ├─ 연장 / 휴일근무 신청서 (OVERTIME)</span></span>
<span class="line"><span> │    ├─ 인사 발령 품의서 (HR_APPOINTMENT)</span></span>
<span class="line"><span> │    └─ 인사 관련 신청서 (HR_REQUEST)</span></span>
<span class="line"><span> ├─ 3. 회계 / 자금 (4종)</span></span>
<span class="line"><span> │    ├─ 구매 품의서 (PURCHASE)</span></span>
<span class="line"><span> │    ├─ 지출 결의서 (EXPENSE)</span></span>
<span class="line"><span> │    ├─ 경비 정산서 (EXPENSE_SETTLEMENT)</span></span>
<span class="line"><span> │    └─ 선급금 / 가지급금 신청서 (ADVANCE)</span></span>
<span class="line"><span> ├─ 4. 계약 / 법무 (3종)</span></span>
<span class="line"><span> │    ├─ 계약 체결 품의서 (CONTRACT)</span></span>
<span class="line"><span> │    ├─ 계약 변경 / 해지 품의서 (CONTRACT_CHANGE)</span></span>
<span class="line"><span> │    └─ 법무 검토 요청서 (LEGAL_REVIEW)</span></span>
<span class="line"><span> └─ 5. 사업 / 프로젝트 (3종)</span></span>
<span class="line"><span>      ├─ 신규 사업 검토서 (BUSINESS_REVIEW)</span></span>
<span class="line"><span>      ├─ 사업 추진 / 예산 승인서 (BUSINESS_APPROVAL)</span></span>
<span class="line"><span>      └─ 프로젝트 주요 의사결정서 (PROJECT_DECISION)</span></span></code></pre></div><h2 id="_1-일반-공통-카테고리" tabindex="-1">1. 일반 / 공통 카테고리 <a class="header-anchor" href="#_1-일반-공통-카테고리" aria-label="Permalink to &quot;1. 일반 / 공통 카테고리&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">양식명 (<code>key</code>)</th><th style="text-align:left;">주요 입력 항목</th><th style="text-align:left;">특징</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>일반 업무 품의서</strong> (<code>GENERAL</code>)</td><td style="text-align:left;">품의 목적, 주요 내용, 기대 효과, 소요 예산</td><td style="text-align:left;">회사 전반의 일반 업무 승인을 위한 표준 서식</td></tr><tr><td style="text-align:left;"><strong>공문 발신 품의서</strong> (<code>OFFICIAL_LETTER</code>)</td><td style="text-align:left;">수신처, 발신 명의, 시행일자, 공문 본문</td><td style="text-align:left;">대외 기관/거래처 발송 공문의 공식 승인 및 채번 연동</td></tr></tbody></table><h2 id="_2-인사-근태-카테고리" tabindex="-1">2. 인사 / 근태 카테고리 <a class="header-anchor" href="#_2-인사-근태-카테고리" aria-label="Permalink to &quot;2. 인사 / 근태 카테고리&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">양식명 (<code>key</code>)</th><th style="text-align:left;">주요 입력 항목</th><th style="text-align:left;">특징</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>휴가 / 연차 신청서</strong> (<code>LEAVE</code>)</td><td style="text-align:left;">휴가 구분(연차/반차/경조/병가), 기간, 차감 일수, 비상연락처</td><td style="text-align:left;">잔여 연차 자동 계산 연동</td></tr><tr><td style="text-align:left;"><strong>출장 신청서</strong> (<code>BUSINESS_TRIP</code>)</td><td style="text-align:left;">출장지, 출장 목적, 기간, 예상 여비 내역</td><td style="text-align:left;">숙박비, 일비, 교통비 산출</td></tr><tr><td style="text-align:left;"><strong>연장 / 휴일근무 신청서</strong> (<code>OVERTIME</code>)</td><td style="text-align:left;">근무 일시, 사전 승인 사유, 예상 근무 시간</td><td style="text-align:left;">주 52시간 근태 관리 연동</td></tr><tr><td style="text-align:left;"><strong>인사 발령 품의서</strong> (<code>HR_APPOINTMENT</code>)</td><td style="text-align:left;">대상자, 발령 구분(승진/전보/보직), 발령 부서/직책</td><td style="text-align:left;">승인 시 <code>StaffAssignment</code> 자동 반영 지원</td></tr><tr><td style="text-align:left;"><strong>인사 관련 신청서</strong> (<code>HR_REQUEST</code>)</td><td style="text-align:left;">신청 구분(증명서 발급/교육 신청/복리후생 지원 등)</td><td style="text-align:left;">기타 인사 총무 요청 처리</td></tr></tbody></table><h2 id="_3-회계-자금-카테고리" tabindex="-1">3. 회계 / 자금 카테고리 <a class="header-anchor" href="#_3-회계-자금-카테고리" aria-label="Permalink to &quot;3. 회계 / 자금 카테고리&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">양식명 (<code>key</code>)</th><th style="text-align:left;">주요 입력 항목</th><th style="text-align:left;">특징</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>구매 품의서</strong> (<code>PURCHASE</code>)</td><td style="text-align:left;">품목명, 규격, 수량, 단가, 공급가액, 부가세, 구입 목적</td><td style="text-align:left;">품목별 소계 및 총액 자동 계산</td></tr><tr><td style="text-align:left;"><strong>지출 결의서</strong> (<code>EXPENSE</code>)</td><td style="text-align:left;">지출 계정, 지급 대상, 지급 기한, 입금 계좌정보, 증빙 목록</td><td style="text-align:left;">전표 및 회계 시스템 연동</td></tr><tr><td style="text-align:left;"><strong>경비 정산서</strong> (<code>EXPENSE_SETTLEMENT</code>)</td><td style="text-align:left;">영수증 일자, 사용처, 금액, 정산 사유, 법인카드 승인번호</td><td style="text-align:left;">출장 및 일상 경비 실비 정산</td></tr><tr><td style="text-align:left;"><strong>선급금 / 가지급금 신청서</strong> (<code>ADVANCE</code>)</td><td style="text-align:left;">신청 금액, 지급 목적, 정산 예정일자</td><td style="text-align:left;">자금 집행 전 선지급 승인</td></tr></tbody></table><h2 id="_4-계약-법무-카테고리" tabindex="-1">4. 계약 / 법무 카테고리 <a class="header-anchor" href="#_4-계약-법무-카테고리" aria-label="Permalink to &quot;4. 계약 / 법무 카테고리&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">양식명 (<code>key</code>)</th><th style="text-align:left;">주요 입력 항목</th><th style="text-align:left;">특징</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>계약 체결 품의서</strong> (<code>CONTRACT</code>)</td><td style="text-align:left;">계약 상대방, 계약 금액, 계약 기간, 주요 조항 요약</td><td style="text-align:left;">계약 체결 사전 의사결정</td></tr><tr><td style="text-align:left;"><strong>계약 변경 / 해지 품의서</strong> (<code>CONTRACT_CHANGE</code>)</td><td style="text-align:left;">원 계약 정보, 변경/해지 사유, 정산 조건</td><td style="text-align:left;">기 체결된 계약의 조건 변경 및 해지</td></tr><tr><td style="text-align:left;"><strong>법무 검토 요청서</strong> (<code>LEGAL_REVIEW</code>)</td><td style="text-align:left;">검토 대상 안건, 주요 법적 쟁점, 계약서 초안 첨부</td><td style="text-align:left;">사내외 변호사 및 법무팀 자문 검토</td></tr></tbody></table><h2 id="_5-사업-프로젝트-카테고리" tabindex="-1">5. 사업 / 프로젝트 카테고리 <a class="header-anchor" href="#_5-사업-프로젝트-카테고리" aria-label="Permalink to &quot;5. 사업 / 프로젝트 카테고리&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">양식명 (<code>key</code>)</th><th style="text-align:left;">주요 입력 항목</th><th style="text-align:left;">특징</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>신규 사업 검토서</strong> (<code>BUSINESS_REVIEW</code>)</td><td style="text-align:left;">대상 사업지, 사업 개요, 수지 분석 요약, 예상 수익률 (IRR)</td><td style="text-align:left;">사업 초기 타당성 검토</td></tr><tr><td style="text-align:left;"><strong>사업 추진 / 예산 승인서</strong> (<code>BUSINESS_APPROVAL</code>)</td><td style="text-align:left;">사업 실행 계획, 단계별 집행 예산, 이사회/경영진 의결 사항</td><td style="text-align:left;">대규모 자금 투입 및 인허가 추진 승인</td></tr><tr><td style="text-align:left;"><strong>프로젝트 주요 의사결정서</strong> (<code>PROJECT_DECISION</code>)</td><td style="text-align:left;">의사결정 배경, 복수 대안 비교표, 권고안, 리스크 평가</td><td style="text-align:left;">설계/시공사 선정, 분양가 책정 등 핵심 결정</td></tr></tbody></table>`,13)])])}const y=e(s,[["render",d]]);export{f as __pageData,y as default};
